// MoonBit moon-egui High-Performance Million-Node Canvas Host Adapter
(function () {
  const canvas = document.getElementById('moon-canvas');
  if (!canvas) return;

  const ctx = canvas.getContext('2d', { alpha: false });
  let width = window.innerWidth;
  let height = window.innerHeight;
  let dpr = window.devicePixelRatio || 1;

  function resizeCanvas() {
    width = window.innerWidth;
    height = window.innerHeight;
    dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    canvas.style.width = width + 'px';
    canvas.style.height = height + 'px';
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.scale(dpr, dpr);
    ctx.imageSmoothingEnabled = false;
    if ('webkitImageSmoothingEnabled' in ctx) ctx.webkitImageSmoothingEnabled = false;
    if ('mozImageSmoothingEnabled' in ctx) ctx.mozImageSmoothingEnabled = false;
    if ('msImageSmoothingEnabled' in ctx) ctx.msImageSmoothingEnabled = false;
  }

  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();

  let mouseX = -100;
  let mouseY = -100;
  let isMouseDown = false;

  let lastX = 0;
  let lastY = 0;
  let panDx = 0;
  let panDy = 0;
  let zoomFactor = 1.0;
  const initialModeAttr = canvas.getAttribute('data-initial-mode');
  let requestedMode = initialModeAttr !== null ? parseInt(initialModeAttr, 10) : -1;

  // Mouse / Pointer Event Listeners
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const currentX = e.clientX - rect.left;
    const currentY = e.clientY - rect.top;

    if (isMouseDown) {
      // Pan drag delta
      panDx += (currentX - lastX);
      panDy += (currentY - lastY);
    }

    mouseX = currentX;
    mouseY = currentY;
    lastX = currentX;
    lastY = currentY;

    updateCursorHud();
  }, { passive: true });

  canvas.addEventListener('mousedown', (e) => {
    if (e.button === 0) {
      isMouseDown = true;
      const rect = canvas.getBoundingClientRect();
      lastX = e.clientX - rect.left;
      lastY = e.clientY - rect.top;
      updateCursorHud();
    }
  });

  window.addEventListener('mouseup', (e) => {
    if (e.button === 0) {
      isMouseDown = false;
      updateCursorHud();
    }
  });

  canvas.addEventListener('mouseleave', () => {
    mouseX = -100;
    mouseY = -100;
    isMouseDown = false;
    updateCursorHud();
  });

  // Wheel Zoom Listener
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    if (e.deltaY < 0) {
      zoomFactor *= 1.15;
    } else {
      zoomFactor *= 0.87;
    }
  }, { passive: false });

  // Expose global mode switcher helper for external UI buttons
  window.switchBenchmarkMode = function (modeIndex) {
    requestedMode = modeIndex;
  };

  window.triggerBenchmarkAction = function (action) {
    if (action === 'fit') requestedMode = 3;
    else if (action === 'scale100') requestedMode = 4;
    else if (action === 'center') requestedMode = 5;
    else if (action === 'drag') requestedMode = 6;
    else if (action === 'pan' || action === 'move') requestedMode = 7;
    else if (action === 'pulse') requestedMode = 1;
    else if (action === 'repel') requestedMode = 2;
    else if (action === '128') requestedMode = 128;
    else if (action === '256') requestedMode = 256;
    else if (action === '512') requestedMode = 512;
    else if (action === '1024') requestedMode = 1024;
  };

  function updateCursorHud() {
    const coordsEl = document.getElementById('telemetry-coords');
    if (coordsEl) {
      coordsEl.textContent = `(${Math.max(0, Math.round(mouseX))}, ${Math.max(0, Math.round(mouseY))})`;
    }
    const stateEl = document.getElementById('telemetry-down');
    if (stateEl) {
      stateEl.textContent = isMouseDown ? 'DRAGGING' : (mouseX >= 0 && mouseY >= 0 ? 'HOVER' : 'IDLE');
      stateEl.className = isMouseDown ? 'status-val status-pressed' : (mouseX >= 0 && mouseY >= 0 ? 'status-val status-hover' : 'status-val');
    }
  }

  // Retrieve step function
  function getStepFn() {
    if (typeof window.moon_step === 'function') return window.moon_step;
    if (typeof globalThis.moon_step === 'function') return globalThis.moon_step;
    for (const key of Object.getOwnPropertyNames(window)) {
      if (key.includes('canvas4step') || (key.includes('moon_2degui') && key.includes('step'))) {
        return window[key];
      }
    }
    return null;
  }

  // Pre-cached canvas state to prevent browser string recalculations
  let cachedFillStyle = '';
  let cachedStrokeStyle = '';
  let cachedLineWidth = -1;
  let cachedFont = '';

  const colorMap = new Map();
  function getColorStr(color) {
    if (!color) return '#000000';
    const key = (color.r << 24) | (color.g << 16) | (color.b << 8) | color.a;
    let s = colorMap.get(key);
    if (!s) {
      s = color.a === 255
        ? `rgb(${color.r},${color.g},${color.b})`
        : `rgba(${color.r},${color.g},${color.b},${(color.a / 255).toFixed(3)})`;
      colorMap.set(key, s);
    }
    return s;
  }

  const fontMap = new Map();
  function getFontStr(fontSize) {
    let f = fontMap.get(fontSize);
    if (!f) {
      f = `600 ${fontSize}px ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace`;
      fontMap.set(fontSize, f);
    }
    return f;
  }

  function setFill(colorStr) {
    if (cachedFillStyle !== colorStr) {
      ctx.fillStyle = colorStr;
      cachedFillStyle = colorStr;
    }
  }

  function setStroke(colorStr, width) {
    if (cachedStrokeStyle !== colorStr) {
      ctx.strokeStyle = colorStr;
      cachedStrokeStyle = colorStr;
    }
    if (cachedLineWidth !== width) {
      ctx.lineWidth = width;
      cachedLineWidth = width;
    }
  }

  function setFont(fontStr) {
    if (cachedFont !== fontStr) {
      ctx.font = fontStr;
      cachedFont = fontStr;
    }
  }

  // Pre-bake Multi-Scale MoonBit Official Logo Matrix Texture Cache (128, 256, 512, 1024)
  const logoCanvases = new Map();
  let logoImg = new Image();
  let logoLoaded = false;
  logoImg.onload = () => {
    logoLoaded = true;
    logoCanvases.clear();
    bakeLogo(128);
    bakeLogo(256);
    bakeLogo(512);
    bakeLogo(1024);
  };
  logoImg.src = "data:image/png;base64,";

  function bakeLogo(dim) {
    if (logoCanvases.has(dim)) return logoCanvases.get(dim);
    const off = document.createElement('canvas');
    off.width = dim;
    off.height = dim;
    const octx = off.getContext('2d', { willReadFrequently: true });
    octx.imageSmoothingEnabled = false;
    if ('webkitImageSmoothingEnabled' in octx) octx.webkitImageSmoothingEnabled = false;
    if ('mozImageSmoothingEnabled' in octx) octx.mozImageSmoothingEnabled = false;
    if ('msImageSmoothingEnabled' in octx) octx.msImageSmoothingEnabled = false;

    if (logoLoaded && logoImg && logoImg.width > 0) {
      octx.drawImage(logoImg, 0, 0, dim, dim);
      const imgData = octx.getImageData(0, 0, dim, dim);
      const data = imgData.data;
      for (let r = 0; r < dim; r++) {
        for (let c = 0; c < dim; c++) {
          const idx = (r * dim + c) * 4;
          const a = data[idx + 3];
          if (a < 64) {
            // Light Theme: Crisp alternating white and slate-100 checkerboard
            const isEven = (c + r) % 2 === 0;
            data[idx] = isEven ? 255 : 241;
            data[idx + 1] = isEven ? 255 : 245;
            data[idx + 2] = isEven ? 255 : 249;
            data[idx + 3] = 255;
          } else {
            data[idx + 3] = 255;
          }
        }
      }
      octx.putImageData(imgData, 0, 0);
      logoCanvases.set(dim, off);
    } else {
      for (let r = 0; r < dim; r++) {
        for (let c = 0; c < dim; c++) {
          octx.fillStyle = (c + r) % 2 === 0 ? '#ffffff' : '#f1f5f9';
          octx.fillRect(c, r, 1, 1);
        }
      }
    }

    return off;
  }

  function getLogoCanvas(dim) {
    let cv = logoCanvases.get(dim);
    if (!cv) {
      cv = bakeLogo(dim);
    }
    return cv;
  }

  // CAD Pixel Grid Lines:
  // Whenever cells reach visible size (unitPx >= 3.5), overlay subtle semi-transparent grid boundary lines.
  // Guarantees every single square in 1,048,576 matrix has crisp, distinct boundaries even in large flat-colored regions.
  function drawPixelGridLines(ctx, gridDim, pitch, zoom, camX, camY, cvX, cvY, cvW, cvH, dstX, dstY, dstW, dstH, scX, scY, unitPx) {
    if (unitPx < 3.5) return;

    const minWx = camX - (cvW * 0.5) / zoom;
    const maxWx = camX + (cvW * 0.5) / zoom;
    const minWy = camY - (cvH * 0.5) / zoom;
    const maxWy = camY + (cvH * 0.5) / zoom;

    const cStart = Math.max(0, Math.floor(minWx / pitch));
    const cEnd = Math.min(gridDim, Math.ceil(maxWx / pitch));
    const rStart = Math.max(0, Math.floor(minWy / pitch));
    const rEnd = Math.min(gridDim, Math.ceil(maxWy / pitch));

    const yTop = Math.max(cvY, dstY);
    const yBottom = Math.min(cvY + cvH, dstY + dstH);
    const xLeft = Math.max(cvX, dstX);
    const xRight = Math.min(cvX + cvW, dstX + dstW);

    if (cEnd <= cStart || rEnd <= rStart || yBottom <= yTop || xRight <= xLeft) return;

    ctx.save();
    ctx.beginPath();
    ctx.rect(cvX, cvY, cvW, cvH);
    ctx.clip();

    // Subtle hairline scaling with zoom level
    const t = Math.min(1.0, Math.max(0.0, (unitPx - 3.5) / 14.0));
    const darkAlpha = 0.08 + t * 0.16; // 0.08 -> 0.24

    ctx.lineWidth = 1;
    ctx.strokeStyle = `rgba(15, 23, 42, ${darkAlpha.toFixed(3)})`;
    ctx.beginPath();

    for (let c = cStart; c <= cEnd; c++) {
      const sx = Math.floor(scX + (c * pitch - camX) * zoom) + 0.5;
      if (sx >= xLeft - 0.5 && sx <= xRight + 0.5) {
        ctx.moveTo(sx, yTop);
        ctx.lineTo(sx, yBottom);
      }
    }

    for (let r = rStart; r <= rEnd; r++) {
      const sy = Math.floor(scY + (r * pitch - camY) * zoom) + 0.5;
      if (sy >= yTop - 0.5 && sy <= yBottom + 0.5) {
        ctx.moveTo(xLeft, sy);
        ctx.lineTo(xRight, sy);
      }
    }
    ctx.stroke();

    if (unitPx >= 8.0) {
      const lightAlpha = Math.min(0.24, Math.max(0.05, (unitPx - 8.0) / 16.0 * 0.22));
      ctx.strokeStyle = `rgba(255, 255, 255, ${lightAlpha.toFixed(3)})`;
      ctx.beginPath();
      for (let c = cStart; c <= cEnd; c++) {
        const sx = Math.floor(scX + (c * pitch - camX) * zoom) + 0.5;
        if (sx >= xLeft - 0.5 && sx <= xRight + 0.5) {
          ctx.moveTo(sx, yTop);
          ctx.lineTo(sx, yBottom);
        }
      }
      for (let r = rStart; r <= rEnd; r++) {
        const sy = Math.floor(scY + (r * pitch - camY) * zoom) + 0.5;
        if (sy >= yTop - 0.5 && sy <= yBottom + 0.5) {
          ctx.moveTo(xLeft, sy);
          ctx.lineTo(xRight, sy);
        }
      }
      ctx.stroke();
    }

    ctx.restore();
  }

  function renderDrawList(dl) {
    if (!dl || !dl.commands) return;

    // Fast clear with clean studio light background
    setFill('#f8fafc');
    ctx.fillRect(0, 0, width, height);

    ctx.imageSmoothingEnabled = false;

    const mState = window.moon_state;
    const gridDim = mState ? mState.grid_dim : 256;
    const pitch = 10000.0 / gridDim;
    const zoom = mState ? mState.zoom : 0.075;
    const camX = mState ? mState.cam_x : 5000;
    const camY = mState ? mState.cam_y : 5000;
    const unitPx = pitch * zoom;

    const cvX = 48.0;
    const cvY = 22.0;
    const cvW = width - 48.0;
    const cvH = height - 22.0;
    const scX = cvX + cvW * 0.5;
    const scY = cvY + cvH * 0.5;

    const dstX = scX + (0 - camX) * zoom;
    const dstY = scY + (0 - camY) * zoom;
    const dstW = 10000 * zoom;
    const dstH = 10000 * zoom;

    // Draw clean white matrix artboard with subtle shadow
    ctx.save();
    ctx.beginPath();
    ctx.rect(cvX, cvY, cvW, cvH);
    ctx.clip();

    ctx.fillStyle = '#ffffff';
    ctx.shadowColor = 'rgba(0, 0, 0, 0.08)';
    ctx.shadowBlur = 16;
    ctx.shadowOffsetY = 4;
    ctx.fillRect(dstX, dstY, dstW, dstH);
    ctx.shadowColor = 'transparent';

    // Strict LOD Threshold:
    // If unitPx < 12.0 || visible_cells > 2500, render the crisp multi-scale baked logo texture (0.02ms).
    // Only when unitPx >= 12.0 && visible_cells <= 2500 does MoonBit stream full interactive vector cells.
    const isMicroVector = (unitPx >= 12.0) && (!mState || (mState.visible_cells !== undefined && mState.visible_cells <= 2500));

    if (!isMicroVector) {
      const baked = getLogoCanvas(gridDim);
      if (baked) {
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(baked, 0, 0, baked.width, baked.height, dstX, dstY, dstW, dstH);
      }
    }
    ctx.restore();

    let gridLinesRendered = false;
    const cmds = dl.commands;
    const len = cmds.length;


    for (let i = 0; i < len; i++) {
      const cmd = cmds[i];
      if (!cmd) continue;

      switch (cmd.$tag) {
        case 0: { // Rect: cmd._0: rect, cmd._1: color, cmd._2: radius
          const rect = cmd._0;
          const color = cmd._1;
          const radius = cmd._2 || 0;
          const colorStr = getColorStr(color);
          setFill(colorStr);

          if (radius <= 1) {
            // Batch consecutive rects of identical color into a single fill call
            if (i + 1 < len && cmds[i + 1] && cmds[i + 1].$tag === 0 && (cmds[i + 1]._2 || 0) <= 1 && cmds[i + 1]._1.r === color.r && cmds[i + 1]._1.g === color.g && cmds[i + 1]._1.b === color.b && cmds[i + 1]._1.a === color.a) {
              ctx.beginPath();
              ctx.rect(rect.x, rect.y, rect.w, rect.h);
              while (i + 1 < len && cmds[i + 1] && cmds[i + 1].$tag === 0 && (cmds[i + 1]._2 || 0) <= 1 && cmds[i + 1]._1.r === color.r && cmds[i + 1]._1.g === color.g && cmds[i + 1]._1.b === color.b && cmds[i + 1]._1.a === color.a) {
                i++;
                const nr = cmds[i]._0;
                ctx.rect(nr.x, nr.y, nr.w, nr.h);
              }
              ctx.fill();
            } else {
              ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
            }
          } else if (ctx.roundRect) {
            ctx.beginPath();
            ctx.roundRect(rect.x, rect.y, rect.w, rect.h, radius);
            ctx.fill();
          } else {
            ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
          }
          break;
        }
        case 1: { // RectStroke: cmd._0: rect, cmd._1: color, cmd._2: strokeW, cmd._3: radius
          const rect = cmd._0;
          const color = cmd._1;
          const strokeW = cmd._2 || 1;
          const radius = cmd._3 || 0;
          const colorStr = getColorStr(color);
          setStroke(colorStr, strokeW);
          ctx.beginPath();
          if (radius > 0 && ctx.roundRect) {
            ctx.roundRect(rect.x, rect.y, rect.w, rect.h, radius);
          } else {
            ctx.rect(rect.x, rect.y, rect.w, rect.h);
          }
          ctx.stroke();
          break;
        }
        case 2: { // Circle: cmd._0: center, cmd._1: radius, cmd._2: color
          const center = cmd._0;
          const radius = cmd._1;
          const color = cmd._2;
          const colorStr = getColorStr(color);
          setFill(colorStr);
          ctx.beginPath();
          ctx.arc(center.x, center.y, radius, 0, Math.PI * 2);
          ctx.fill();
          break;
        }
        case 3: { // CircleStroke: cmd._0: center, cmd._1: radius, cmd._2: color, cmd._3: strokeW
          const center = cmd._0;
          const radius = cmd._1;
          const color = cmd._2;
          const strokeW = cmd._3 || 1;
          const colorStr = getColorStr(color);
          setStroke(colorStr, strokeW);
          ctx.beginPath();
          ctx.arc(center.x, center.y, radius, 0, Math.PI * 2);
          ctx.stroke();
          break;
        }
        case 4: { // Line: cmd._0: p1, cmd._1: p2, cmd._2: color, cmd._3: strokeW
          const p1 = cmd._0;
          const p2 = cmd._1;
          const color = cmd._2;
          const strokeW = cmd._3 || 1;
          const colorStr = getColorStr(color);
          setStroke(colorStr, strokeW);

          // Batch consecutive lines of identical stroke & color
          ctx.beginPath();
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          while (i + 1 < len && cmds[i + 1] && cmds[i + 1].$tag === 4 && (cmds[i + 1]._3 || 1) === strokeW && cmds[i + 1]._2.r === color.r && cmds[i + 1]._2.g === color.g && cmds[i + 1]._2.b === color.b && cmds[i + 1]._2.a === color.a) {
            i++;
            const np1 = cmds[i]._0;
            const np2 = cmds[i]._1;
            ctx.moveTo(np1.x, np1.y);
            ctx.lineTo(np2.x, np2.y);
          }
          ctx.stroke();
          break;
        }
        case 5: { // Text: cmd._0: pos, cmd._1: text, cmd._2: fontSize, cmd._3: color
          const pos = cmd._0;
          const text = cmd._1;
          const fontSize = cmd._2 || 14;
          const color = cmd._3;
          const colorStr = getColorStr(color);
          setFill(colorStr);
          setFont(getFontStr(fontSize));
          ctx.textBaseline = 'top';
          ctx.fillText(text, pos.x, pos.y);
          break;
        }
        case 6: { // Clip: cmd._0: rect
          const rect = cmd._0;
          ctx.save();
          ctx.beginPath();
          ctx.rect(rect.x, rect.y, rect.w, rect.h);
          ctx.clip();
          break;
        }
        case 7: { // ResetClip
          // Render CAD pixel grid lines directly on top of the matrix before popping workspace clip,
          // ensuring grid lines are on top of cells and under CAD rulers.
          if (!gridLinesRendered) {
            drawPixelGridLines(ctx, gridDim, pitch, zoom, camX, camY, cvX, cvY, cvW, cvH, dstX, dstY, dstW, dstH, scX, scY, unitPx);
            gridLinesRendered = true;
          }
          ctx.restore();
          break;
        }
      }
    }

    if (!gridLinesRendered) {
      drawPixelGridLines(ctx, gridDim, pitch, zoom, camX, camY, cvX, cvY, cvW, cvH, dstX, dstY, dstW, dstH, scX, scY, unitPx);
      gridLinesRendered = true;
    }

    const cmdsEl = document.getElementById('telemetry-cmds');
    if (cmdsEl) {
      cmdsEl.textContent = len.toLocaleString();
    }
  }

  let stepFn = null;
  let lastFpsTime = performance.now();
  let frameCounter = 0;
  let fps = 60;
  let kernelTimeRolling = 0.25;

  function loop(now) {
    frameCounter++;
    if (now - lastFpsTime >= 500) {
      if (!document.hidden && now - lastFpsTime < 2000) {
        fps = Math.round((frameCounter * 1000) / (now - lastFpsTime));
        const fpsEl = document.getElementById('telemetry-fps');
        if (fpsEl) fpsEl.textContent = (Math.max(1, fps)).toFixed(1);
      }
      frameCounter = 0;
      lastFpsTime = now;
    }

    if (!stepFn) {
      stepFn = getStepFn();
    }

    if (stepFn) {
      // Step with camera pan and zoom delta
      const curPanX = panDx;
      const curPanY = panDy;
      const curZoom = zoomFactor;
      const curMode = requestedMode;

      // Consume one-shot deltas
      panDx = 0;
      panDy = 0;
      zoomFactor = 1.0;
      requestedMode = -1;

      const t0 = performance.now();
      const dl = stepFn(mouseX, mouseY, isMouseDown, curPanX, curPanY, curZoom, curMode, width, height);
      const dt = performance.now() - t0;

      kernelTimeRolling = kernelTimeRolling * 0.85 + dt * 0.15;

      renderDrawList(dl);

      // Telemetry updates
      const kernelEl = document.getElementById('telemetry-kernel');
      if (kernelEl) {
        kernelEl.textContent = `${kernelTimeRolling.toFixed(2)} ms`;
      }

      const budgetPct = Math.min(100, Math.max(0.1, (kernelTimeRolling / 16.666) * 100));
      const budgetPctEl = document.getElementById('telemetry-budget-pct');
      if (budgetPctEl) {
        budgetPctEl.textContent = `${budgetPct.toFixed(1)}%`;
      }

      const budgetBar = document.getElementById('telemetry-budget-bar');
      if (budgetBar) {
        budgetBar.style.width = `${budgetPct}%`;
      }

      const mState = window.moon_state || globalThis.moon_state;
      const gridDim = mState ? mState.grid_dim : 256;
      const totalNodes = gridDim * gridDim;
      const nodesEl = document.getElementById('txt-nodes');
      if (nodesEl) {
        nodesEl.textContent = `${totalNodes.toLocaleString()} 节点 (${gridDim}×${gridDim})`;
      }
      const throughputEl = document.getElementById('telemetry-throughput');
      if (throughputEl) {
        throughputEl.textContent = `${totalNodes.toLocaleString()} Nodes`;
      }
    }

    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
